/**
 * The contract `item.tsx` (native) and `item.web.tsx` (web) both implement: shadcn's `Item` parts,
 * with the part of each one's classes that Yoga can read. Its own module because Metro resolves
 * `./item` to `item.web.tsx` on web.
 *
 * Each class here is what the two halves agree on; the web half adds what only the DOM has —
 * `group-has-[…]`, `[&_svg]`, `[a]:`, the focus ring, `text-balance` — and the native half adds a
 * `Text` around a string and the ink a `Text` does not inherit there.
 *
 * `default` is shadcn's size, so a DOM app's rows draw as they did. `sm` is `ListItem`'s row, which
 * is built from these parts at that size, and it takes the heading rhythm every block and row
 * shares (`HEADING_TITLE` and the rest, in `@/lib/utils`). A part that changes with the size has a
 * `_SIZES` map, which the native half picks from by the row's size in context, and a `_SM_WEB`
 * string: the same `sm` classes behind the row's `data-size`, for the web half, whose parts stay
 * plain DOM. The `_SM_WEB` strings spell the rhythm's classes out, because a variant has to be a
 * literal for Tailwind to find it; `Heading rhythm` in the stories holds the two halves together.
 */
import { cva } from "class-variance-authority";
import {
  cn,
  HEADING_DESCRIPTION,
  HEADING_GAP,
  HEADING_TITLE,
  HEADING_WRAP_FLOOR,
  HEADING_WRAP_GAP,
} from "@/lib/utils";

/** How an `Item`'s surface is drawn. */
export type ItemVariant = "default" | "outline" | "muted";
/** How much padding an `Item` has. */
export type ItemSize = "default" | "sm";
/** What `ItemMedia` holds, which picks its box. */
export type ItemMediaVariant = "default" | "icon" | "image";

/**
 * The row: its children side by side, wrapping — `ItemHeader` and `ItemFooter` take a line of their
 * own. `outline` is the bordered card-per-row, `muted` a filled one.
 */
export const itemVariants = cva(
  "flex-row flex-wrap items-center rounded-md border border-transparent",
  {
    variants: {
      variant: {
        default: "bg-transparent",
        outline: "border-foreground/10",
        muted: "bg-foreground/10",
      },
      size: {
        default: "gap-4 p-4",
        // `ListItem`'s row: 12px across and 8px down to the content, and no edge, so a border a
        // caller adds (`border border-foreground/10` for a card per row) goes outside that, as it
        // always did on `ListItem`. A line the row wraps onto is the rhythm's 8px under the last.
        sm: cn("gap-3 border-0 px-3 py-2", HEADING_WRAP_GAP),
      },
    },
    compoundVariants: [
      // The outline draws its edge inside the same box, so an outlined row and a plain one are
      // the same size at `sm` as they are at shadcn's own.
      { variant: "outline", size: "sm", className: "border px-2.75 py-1.75" },
    ],
    defaultVariants: { variant: "default", size: "default" },
  },
);

/**
 * The chosen row: the one whose record is open beside the list. A tint in `active` and not the
 * hover grey, which on a row that stays put reads as a hover that stuck. The colour is not the
 * whole of it: say which row it is with `aria-current` on the link, or `aria-selected` in a listbox.
 */
export const ITEM_SELECTED_CLASS = "bg-active/40";

/**
 * The muted line's ink on the chosen row. `text-foreground/60` is 4.2:1 on the tint, short of the
 * 4.5:1 text needs, so on that row the description is full `foreground`, as ListItem's is.
 */
export const ITEM_SELECTED_DESCRIPTION_CLASS = "text-foreground";

/**
 * The start of the row: an icon in a small tile, an image, or whatever is passed. On the web an
 * `<svg>` or `<img>` inside is sized for you; on a device pass it sized (`size-4`, `size-full`).
 */
export const itemMediaVariants = cva("shrink-0 flex-row items-center justify-center gap-2", {
  variants: {
    variant: {
      default: "bg-transparent",
      // The fill alone, as EmptyMedia's tile: a ring on top of it was a second edge on one boundary.
      icon: "size-8 rounded-sm bg-foreground/10",
      image: "size-10 overflow-hidden rounded-sm",
    },
  },
  defaultVariants: { variant: "default" },
});

/** The middle: the title over the description, taking the row's spare width. */
export const ITEM_CONTENT_CLASS = "flex-1";

/**
 * At `sm` the two lines are the rhythm's `HEADING_GAP` apart, and the middle gives way to a long
 * title instead of growing, down to the rhythm's wrap floor: below 10rem the actions go under it.
 */
export const ITEM_CONTENT_SIZES = {
  default: "gap-1",
  sm: cn(HEADING_WRAP_FLOOR, HEADING_GAP),
} as const;
export const ITEM_CONTENT_SM_WEB =
  "group-data-[size=sm]/item:min-w-0 group-data-[size=sm]/item:basis-40 group-data-[size=sm]/item:gap-1";

/** The title's line: text, a badge beside it, side by side. */
export const ITEM_TITLE_CLASS = "flex-row items-center gap-2";

/**
 * At `sm` the line is held to the row's width, so a title truncated inside it has an edge to stop
 * at. Sized to its content, it ran past the row instead.
 */
export const ITEM_TITLE_SIZES = { default: "", sm: "max-w-full" } as const;
export const ITEM_TITLE_SM_WEB = "group-data-[size=sm]/item:max-w-full";

/** The title's type. On a device it goes on the `Text` a string is wrapped in, with its ink. */
export const ITEM_TITLE_TEXT = "text-sm font-semibold";

/**
 * At `sm` the title is the rhythm's `HEADING_TITLE`, on `text-sm`'s own 20px line. On the web the
 * line height is the title line's, which a `Text` inside inherits, so that half says `leading-5`,
 * the same 20px, to undo `leading-snug`.
 */
export const ITEM_TITLE_TEXT_SIZES = { default: "leading-snug", sm: HEADING_TITLE } as const;
export const ITEM_TITLE_TEXT_SM_WEB = "group-data-[size=sm]/item:leading-5";

/** The muted line under the title, two lines at most. */
export const ITEM_DESCRIPTION_CLASS = "line-clamp-2 font-normal text-foreground/60";

/**
 * At `sm` the description is the rhythm's `HEADING_DESCRIPTION`: the title's size, quieter by ink.
 * On the web `leading-5` is `text-sm`'s own 20px, said because `leading-normal` would carry over,
 * and the line is filled rather than balanced and keeps a string's newlines, as a native `Text`
 * does.
 */
export const ITEM_DESCRIPTION_SIZES = {
  default: "text-sm leading-normal",
  sm: HEADING_DESCRIPTION,
} as const;
export const ITEM_DESCRIPTION_SM_WEB =
  "group-data-[size=sm]/item:leading-5 group-data-[size=sm]/item:text-wrap group-data-[size=sm]/item:whitespace-pre-wrap";

/** The far end: buttons, a menu. */
export const ITEM_ACTIONS_CLASS = "flex-row items-center";

/**
 * At `sm` the buttons are level with the title's top rather than centred on the row, and never
 * give their width up to a long title. On a row that wraps, a wrapped action keeps to the far end,
 * clear of the row's media. Their gap is the rhythm's, by what they are: `actionGap` in
 * `@/lib/utils`, 4px between `icon-xs` buttons and 8px otherwise.
 */
export const ITEM_ACTIONS_SIZES = { default: "gap-2", sm: "ml-auto shrink-0 self-start" } as const;
export const ITEM_ACTIONS_SM_WEB =
  "group-data-[size=sm]/item:ml-auto group-data-[size=sm]/item:shrink-0 group-data-[size=sm]/item:self-start";

/**
 * The web half's gap between `icon-xs` buttons at `sm`, behind the row's `data-size`: the rest
 * keep the `gap-2` both sizes start from. `default` stays shadcn's whatever the buttons are.
 */
export const ITEM_ACTIONS_ICON_GAP_SM_WEB = "group-data-[size=sm]/item:gap-1";

/** A full-width line above the rest of the row. */
export const ITEM_HEADER_CLASS = "flex-row items-center justify-between gap-2";

/** A full-width line below the rest of the row. */
export const ITEM_FOOTER_CLASS = "flex-row items-center justify-between gap-2";

/** The rule between rows in an `ItemGroup`: a `Separator`, with shadcn's reset margin. */
export const ITEM_SEPARATOR_CLASS = "my-0";

/**
 * shadcn's `Item` parts on React Native, under shadcn's names and with its `variant` and `size`.
 * `item.web.tsx` is the web counterpart and `item-base.ts` holds the classes they share.
 *
 * These are for a row `ListItem` does not fit: a header line, a footer that opens, a title with a
 * badge beside it. `ListItem` is these parts at `size="sm"`, so a row composed from them at that
 * size lines up with the `ListItem`s beside it. A string passed to a part is wrapped in a `Text`,
 * since a bare string in a `View` throws on device. `ItemMedia` does not size what is in it, as
 * there is no `[&_svg]` selector: pass an icon at `size-4`.
 */
import { Slot } from "@radix-ui/react-slot";
import * as React from "react";
import { Text, View } from "react-native";
import {
  ITEM_ACTIONS_CLASS,
  ITEM_ACTIONS_SIZES,
  ITEM_CONTENT_CLASS,
  ITEM_CONTENT_SIZES,
  ITEM_DESCRIPTION_CLASS,
  ITEM_DESCRIPTION_SIZES,
  ITEM_FOOTER_CLASS,
  ITEM_HEADER_CLASS,
  ITEM_SELECTED_CLASS,
  ITEM_SELECTED_DESCRIPTION_CLASS,
  ITEM_SEPARATOR_CLASS,
  ITEM_TITLE_CLASS,
  ITEM_TITLE_SIZES,
  ITEM_TITLE_TEXT,
  ITEM_TITLE_TEXT_SIZES,
  type ItemMediaVariant,
  type ItemSize,
  type ItemVariant,
  itemMediaVariants,
  itemVariants,
} from "@/components/ui/item-base";
import { Separator, type SeparatorProps } from "@/components/ui/separator";
import { actionGap, cn } from "@/lib/utils";

// `className` is re-declared rather than inherited: nativewind types it as `className?: string`,
// which under `exactOptionalPropertyTypes` rejects the conditional a call site passes.
type ViewProps = Omit<React.ComponentProps<typeof View>, "className"> & {
  className?: string | undefined;
};
type TextProps = Omit<React.ComponentProps<typeof Text>, "className"> & {
  className?: string | undefined;
};

/** The ink and type a string in a part is drawn with, where nothing is inherited. */
const PART_TEXT = "text-foreground text-sm";

/**
 * Each string or number child in its own `Text`, elements left as they are. A part holds a badge
 * beside a word as often as a word alone, so it is the children one by one, not all or nothing.
 */
function withText(children: React.ReactNode, className: string) {
  return React.Children.map(children, (child) =>
    typeof child === "string" || typeof child === "number" ? (
      <Text className={className}>{child}</Text>
    ) : (
      child
    ),
  );
}

/** A list of items. */
function ItemGroup({ className, ...props }: ViewProps) {
  return <View testID="item-group" className={cn("flex-col", className)} {...props} />;
}

/** A rule between two items. */
function ItemSeparator({ className, ...props }: SeparatorProps) {
  return (
    <Separator testID="item-separator" className={cn(ITEM_SEPARATOR_CLASS, className)} {...props} />
  );
}

type ItemProps = ViewProps & {
  variant?: ItemVariant | null | undefined;
  size?: ItemSize | null | undefined;
  /**
   * Hand the row's classes to the one child instead of a `View` around it — a `Pressable` that
   * opens the record, an expo-router `Link`. Radix's `Slot`, as on `Button`.
   */
  asChild?: boolean | undefined;
  /**
   * The chosen row: the one open beside the list. Tinted in `active`. Set `aria-current` or
   * `aria-selected` on the row or the link inside as well.
   */
  selected?: boolean | undefined;
};

/**
 * What the parts need to know about the row they are in, since nothing is inherited on a device:
 * whether it is the chosen one, for the description's ink, and its size, for each part's metrics.
 */
const ItemRowContext = React.createContext<{ selected: boolean; size: ItemSize }>({
  selected: false,
  size: "default",
});

/** One row: media, content and actions side by side. */
function Item({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  selected = false,
  ...props
}: ItemProps) {
  const classes = cn(itemVariants({ variant, size }), selected && ITEM_SELECTED_CLASS, className);
  const row = React.useMemo(() => ({ selected, size: size ?? "default" }), [selected, size]);
  if (asChild) {
    // `Slot` is typed for the DOM, but it renders nothing of its own — it clones the caller's
    // one child with these props merged in — so the cast is the honest way to say neither side's
    // typing describes it (`Button` does the same).
    return (
      <ItemRowContext.Provider value={row}>
        <Slot className={classes} {...(props as unknown as React.HTMLAttributes<HTMLElement>)} />
      </ItemRowContext.Provider>
    );
  }
  return (
    <ItemRowContext.Provider value={row}>
      <View testID="item" className={classes} {...props} />
    </ItemRowContext.Provider>
  );
}

type ItemMediaProps = ViewProps & { variant?: ItemMediaVariant | null | undefined };

/** The icon or image at the start of an item. */
function ItemMedia({ className, variant = "default", ...props }: ItemMediaProps) {
  return (
    <View
      testID="item-media"
      className={cn(itemMediaVariants({ variant }), className)}
      {...props}
    />
  );
}

/** The middle of an item, holding its title and description. */
function ItemContent({ className, children, ...props }: ViewProps) {
  const { size } = React.useContext(ItemRowContext);
  return (
    <View
      testID="item-content"
      className={cn(ITEM_CONTENT_CLASS, ITEM_CONTENT_SIZES[size], className)}
      {...props}
    >
      {withText(children, PART_TEXT)}
    </View>
  );
}

/**
 * A `View` holding the line, not a `Text`, because the line is as often a badge beside a word as a
 * word — and a `View` inside a `Text` is not a row on a device. The string gets the title's type.
 */
function ItemTitle({ className, children, ...props }: ViewProps) {
  const { size } = React.useContext(ItemRowContext);
  return (
    <View
      testID="item-title"
      className={cn("self-start", ITEM_TITLE_CLASS, ITEM_TITLE_SIZES[size], className)}
      {...props}
    >
      {withText(children, cn("text-foreground", ITEM_TITLE_TEXT, ITEM_TITLE_TEXT_SIZES[size]))}
    </View>
  );
}

/** The muted line under the item's title. */
function ItemDescription({ className, ...props }: TextProps) {
  const { selected, size } = React.useContext(ItemRowContext);
  return (
    <Text
      testID="item-description"
      className={cn(
        ITEM_DESCRIPTION_CLASS,
        ITEM_DESCRIPTION_SIZES[size],
        selected && ITEM_SELECTED_DESCRIPTION_CLASS,
        className,
      )}
      {...props}
    />
  );
}

/** The buttons at the far end of an item. */
function ItemActions({ className, children, ...props }: ViewProps) {
  const { size } = React.useContext(ItemRowContext);
  return (
    <View
      testID="item-actions"
      className={cn(
        ITEM_ACTIONS_CLASS,
        ITEM_ACTIONS_SIZES[size],
        // `default` keeps shadcn's gap whatever the buttons are.
        size === "sm" && actionGap(children),
        className,
      )}
      {...props}
    >
      {withText(children, PART_TEXT)}
    </View>
  );
}

/** A full-width line above the item's row. */
function ItemHeader({ className, children, ...props }: ViewProps) {
  return (
    <View testID="item-header" className={cn("w-full", ITEM_HEADER_CLASS, className)} {...props}>
      {withText(children, PART_TEXT)}
    </View>
  );
}

/** A full-width line below the item's row. */
function ItemFooter({ className, children, ...props }: ViewProps) {
  return (
    <View testID="item-footer" className={cn("w-full", ITEM_FOOTER_CLASS, className)} {...props}>
      {withText(children, PART_TEXT)}
    </View>
  );
}

export {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemFooter,
  ItemGroup,
  ItemHeader,
  ItemMedia,
  ItemSeparator,
  ItemTitle,
};

/**
 * The web `Item`: shadcn's parts, with shadcn's props and markup, so a DOM call site that installed
 * `@cubeui/item` before it had a native half compiles and draws as it did. `item.tsx` is the
 * native counterpart and `item-base.ts` holds the classes the two share; what is added here is
 * what only the DOM has.
 *
 * It is hand-written rather than compiled for three reasons the compiler would have to guess at:
 * `ItemDescription` is shadcn's `<p>` taking `<p>` props, the parts read the row's size and state
 * from its `data-size` and `data-selected` rather than from context, so they stay plain DOM, and
 * the compiled reset (`flex-shrink: 0` on every view) would stop a long title shrinking inside a
 * row that shadcn lets shrink — the thing `CollapsibleRow`'s truncating title depends on.
 *
 * `ItemSeparator` is `@cubeui/separator`'s `Separator`, as shadcn's is its own.
 */
import type { VariantProps } from "class-variance-authority";
import { Slot } from "radix-ui";
import type * as React from "react";
import {
  ITEM_ACTIONS_CLASS,
  ITEM_ACTIONS_ICON_GAP_SM_WEB,
  ITEM_ACTIONS_SIZES,
  ITEM_ACTIONS_SM_WEB,
  ITEM_CONTENT_CLASS,
  ITEM_CONTENT_SIZES,
  ITEM_CONTENT_SM_WEB,
  ITEM_DESCRIPTION_CLASS,
  ITEM_DESCRIPTION_SIZES,
  ITEM_DESCRIPTION_SM_WEB,
  ITEM_FOOTER_CLASS,
  ITEM_HEADER_CLASS,
  ITEM_SELECTED_CLASS,
  ITEM_SEPARATOR_CLASS,
  ITEM_TITLE_CLASS,
  ITEM_TITLE_SM_WEB,
  ITEM_TITLE_TEXT,
  ITEM_TITLE_TEXT_SIZES,
  ITEM_TITLE_TEXT_SM_WEB,
  itemMediaVariants,
  itemVariants,
} from "@/components/ui/item-base";
import { Separator, type SeparatorProps } from "@/components/ui/separator";
import { actionGap, cn, ICON_ACTION_GAP } from "@/lib/utils";

/**
 * A part's name in a test. A native source drawn on the web — `ListItem` in an Expo web build,
 * which resolves this file beside `item.tsx` — names a part with `testID`, as it does on device.
 * The DOM's word for that is `data-slot`, so it is written there in place of the part's own.
 */
type Named = { testID?: string | undefined };

/**
 * Upstream ships this with `role="list"`, and it is dropped here on purpose: nothing in this
 * file can be the `listitem` that role requires. `Item` takes `asChild`, so a caller may render
 * it as an `<a>` or a `<button>`, and a fixed role here would clobber that one — which is why
 * upstream does not put it there either. A `list` owning no `listitem` is not a neutral
 * overclaim: it announces as an empty list, and an AT that exposes only listitem children hides
 * whatever is inside it. A caller that really is drawing a list can say so on its own wrapper,
 * which is also where it owns the items.
 */
function ItemGroup({ className, testID, ...props }: React.ComponentProps<"div"> & Named) {
  return (
    <div
      data-slot={testID ?? "item-group"}
      className={cn("group/item-group flex flex-col", className)}
      {...props}
    />
  );
}

/** A rule between two items. */
function ItemSeparator({ className, testID, ...props }: SeparatorProps & Named) {
  return (
    <Separator
      data-slot={testID ?? "item-separator"}
      className={cn(ITEM_SEPARATOR_CLASS, className)}
      {...props}
    />
  );
}

/** What only a DOM row has: the hover on a link row, and the focus ring. */
const ITEM_WEB =
  "group/item flex transition-colors duration-100 outline-none [a]:transition-colors [a]:hover:bg-hover [a]:focus-visible:bg-hover";

/**
 * shadcn's type for the whole row, at its own size only. At `sm` the parts set their own, as
 * `ListItem`'s always did, so what a caller puts in a slot keeps the page's type around it.
 */
const ITEM_TEXT_WEB = "data-[size=default]:text-sm";

/** A header's or footer's words at `sm`, which the row no longer sizes: the device half's size. */
const ITEM_LINE_TEXT_WEB = "group-data-[size=sm]/item:text-sm";

/** One row: media, content and actions side by side. */
function Item({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  selected = false,
  testID,
  ...props
}: React.ComponentProps<"div"> &
  VariantProps<typeof itemVariants> &
  Named & {
    asChild?: boolean;
    /**
     * The chosen row: the one open beside the list. Tinted in `active`, a step further under the
     * pointer. Set `aria-current` or `aria-selected` on the row or the link inside as well.
     */
    selected?: boolean | undefined;
  }) {
  const Comp = asChild ? Slot.Root : "div";
  return (
    <Comp
      data-slot={testID ?? "item"}
      data-variant={variant}
      data-size={size}
      data-selected={selected ? "" : undefined}
      className={cn(
        ITEM_WEB,
        ITEM_TEXT_WEB,
        itemVariants({ variant, size }),
        selected && ITEM_SELECTED_CLASS,
        selected && "[a]:hover:bg-active/60 [a]:focus-visible:bg-active/60",
        className,
      )}
      {...props}
    />
  );
}

/** Sizing what is inside, which a device cannot select for, and the nudge beside a description. */
const ITEM_MEDIA_WEB = {
  default: "",
  icon: "[&_svg:not([class*='size-'])]:size-4",
  image: "[&_img]:size-full [&_img]:object-cover",
} as const;

/** The icon or image at the start of an item. */
function ItemMedia({
  className,
  variant = "default",
  testID,
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof itemMediaVariants> & Named) {
  return (
    <div
      data-slot={testID ?? "item-media"}
      data-variant={variant}
      className={cn(
        "flex [&_svg]:pointer-events-none",
        // shadcn's nudge to the description's first line, at its own size only: at `sm` the media
        // stays centred on the row, as `ListItem`'s `leadingSlot` is.
        "group-data-[size=default]/item:group-has-[[data-slot=item-description]]/item:translate-y-0.5 group-data-[size=default]/item:group-has-[[data-slot=item-description]]/item:self-start",
        itemMediaVariants({ variant }),
        ITEM_MEDIA_WEB[variant ?? "default"],
        className,
      )}
      {...props}
    />
  );
}

/** The middle of an item, holding its title and description. */
function ItemContent({ className, testID, ...props }: React.ComponentProps<"div"> & Named) {
  return (
    <div
      data-slot={testID ?? "item-content"}
      className={cn(
        "flex flex-col [&+[data-slot=item-content]]:flex-none",
        ITEM_CONTENT_CLASS,
        ITEM_CONTENT_SIZES.default,
        ITEM_CONTENT_SM_WEB,
        className,
      )}
      {...props}
    />
  );
}

/** The item's title. */
function ItemTitle({ className, testID, ...props }: React.ComponentProps<"div"> & Named) {
  return (
    <div
      data-slot={testID ?? "item-title"}
      className={cn(
        "flex w-fit",
        ITEM_TITLE_CLASS,
        ITEM_TITLE_SM_WEB,
        ITEM_TITLE_TEXT,
        ITEM_TITLE_TEXT_SIZES.default,
        ITEM_TITLE_TEXT_SM_WEB,
        className,
      )}
      {...props}
    />
  );
}

/** The muted line under the item's title. */
function ItemDescription({ className, testID, ...props }: React.ComponentProps<"p"> & Named) {
  return (
    <p
      data-slot={testID ?? "item-description"}
      className={cn(
        ITEM_DESCRIPTION_CLASS,
        ITEM_DESCRIPTION_SIZES.default,
        ITEM_DESCRIPTION_SM_WEB,
        // ITEM_SELECTED_DESCRIPTION_CLASS on the chosen row, which says so with `data-selected`:
        // read here rather than through context so the part stays a plain `<p>`.
        "in-data-selected:text-foreground",
        // A link is `info` at rest, as every link is, and shown by its underline as well. On the
        // chosen row it is `foreground`: `info` on the tint is about 3.3:1, under AA.
        "text-balance [&>a]:text-info [&>a]:underline [&>a]:underline-offset-4",
        "in-data-selected:[&>a]:text-foreground",
        className,
      )}
      {...props}
    />
  );
}

/** The buttons at the far end of an item. */
function ItemActions({
  className,
  testID,
  children,
  ...props
}: React.ComponentProps<"div"> & Named) {
  return (
    <div
      data-slot={testID ?? "item-actions"}
      className={cn(
        "flex",
        ITEM_ACTIONS_CLASS,
        ITEM_ACTIONS_SIZES.default,
        ITEM_ACTIONS_SM_WEB,
        actionGap(children) === ICON_ACTION_GAP && ITEM_ACTIONS_ICON_GAP_SM_WEB,
        className,
      )}
      {...props}
